pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testRegression_property() public {
        address logAddr = address(new LogFile());
        c.SetLogFile(logAddr);
        c.SetMinSum(0);
        c.Initialized();

        address user = address(0x1);
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.Deposit{value: 1 wei}();

        bool success;
        vm.prank(user);
        try c.Collect(1) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    receive() external payable {
        revert();
    }

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
